(5412210, 777451, 104776, '<td valign="top">Great bokeh.  Good focus on the needles.  Would have liked to have seen the drop of ice in focus as well, however.</td>', 'Great bokeh.  Good focus on the needles.  Would have liked to have seen the drop of ice in focus as well, however.', '2009-04-01 11:55:44.000000', NULL, 1),
(5412212, 776751, 104776, '<td valign="top">Good bokeh and colors.  Nice focus too.</td>', 'Good bokeh and colors.  Nice focus too.', '2009-04-01 11:56:25.000000', NULL, 1),
(5412218, 777928, 104776, '<td valign="top">Very, very nice focus and bokeh!!  The backgound is blurred perfectly and the variation in background color is very interesting.  Great job!</td>', 'Very, very nice focus and bokeh!!  The backgound is blurred perfectly and the variation in background color is very interesting.  Great job!', '2009-04-01 11:57:06.000000', NULL, 1),
(5412220, 777930, 104776, '<td valign="top">Cool idea, but a wee bit too dark.</td>', 'Cool idea, but a wee bit too dark.', '2009-04-01 11:57:34.000000', NULL, 1),
