(5412223, 778400, 104776, '<td valign="top">Great composition and colors.  The blades in front of the flowers and nearest the lens, however, are a bit of a distraction.</td>', 'Great composition and colors.  The blades in front of the flowers and nearest the lens, however, are a bit of a distraction.', '2009-04-01 11:58:55.000000', NULL, 1),
(5412224, 778409, 104776, '<td valign="top">Simple and effective.  Little bit boring though.  But a pretty good shot overall.</td>', 'Simple and effective.  Little bit boring though.  But a pretty good shot overall.', '2009-04-01 11:59:47.000000', NULL, 1),
(5412226, 777955, 104776, '<td valign="top">Nicely composed and good job on the focus.  Very nice photo indeed.</td>', 'Nicely composed and good job on the focus.  Very nice photo indeed.', '2009-04-01 12:00:19.000000', NULL, 1),
