INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5412330, 777810, 92475, '<td valign="top">Ouch! My EYES!</td>', 'Ouch! My EYES!', '2009-04-01 12:43:30.000000', NULL, 1),
(5412338, 777363, 104776, '<td valign="top">Ha!  LOVE the concept.  Very clever and well done.  Great light/focus/color.</td>', 'Ha!  LOVE the concept.  Very clever and well done.  Great light/focus/color.', '2009-04-01 12:48:22.000000', NULL, 1),
(5412350, 778624, 98141, '<td valign="top">I think this would pop more if the background were evenly lit. The bright spot on the wall seems like it''s in a weird place to me - it''s not right by the blossom and it''s not even, so what is it highlighting?</td>', 'I think this would pop more if the background were evenly lit. The bright spot on the wall seems like it''s in a weird place to me - it''s not right by the blossom and it''s not even, so what is it highlighting?', '2009-04-01 12:51:01.000000', NULL, 1),
(5412353, 778337, 98141, '<td valign="top">Beautiful specimen and I like that it''s very natural-looking. Great bokeh and I love the square frame.</td>', 'Beautiful specimen and I like that it''s very natural-looking. Great bokeh and I love the square frame.', '2009-04-01 12:51:43.000000', NULL, 1),
(5412368, 777147, 98141, '<td valign="top">Interesting processing on this, makes it feel very antique-y. I like the smokey look to the lines in the background. I think the white balance feels a bit off, perhaps it''s the antique-y look, maybe not.</td>', 'Interesting processing on this, makes it feel very antique-y. I like the smokey look to the lines in the background. I think the white balance feels a bit off, perhaps it''s the antique-y look, maybe not.', '2009-04-01 12:58:07.000000', NULL, 1),
(5412372, 778528, 98141, '<td valign="top">There is a weird purple line outlining some of the branch. I''m having trouble tell what is in focus. I like the color of the green. Not a fan of the border or the grey background.</td>', 'There is a weird purple line outlining some of the branch. I''m having trouble tell what is in focus. I like the color of the green. Not a fan of the border or the grey background.', '2009-04-01 13:00:30.000000', NULL, 1),
(5412375, 777117, 98141, '<td valign="top">Great colors, the pink/purple really pops, as does the yellow. I dig the black and white background, it''s elegant and helps to emphasize the colors even more. I wish the dof were a little more inclusive, but overall nice shot.</td>', 'Great colors, the pink/purple really pops, as does the yellow. I dig the black and white background, it''s elegant and helps to emphasize the colors even more. I wish the dof were a little more inclusive, but overall nice shot.', '2009-04-01 13:01:37.000000', NULL, 1),
(5412378, 778647, 98141, '<td valign="top">I think the dark line of mountains really prevents us from seeing the treeline better, which I think would make this photo more interesting. Perhaps a lower angle could have minimized that problem? I also think the colors could pop a bit more. I like the composition/placement of the big tree though.</td>', 'I think the dark line of mountains really prevents us from seeing the treeline better, which I think would make this photo more interesting. Perhaps a lower angle could have minimized that problem? I also think the colors could pop a bit more. I like the composition/placement of the big tree though.', '2009-04-01 13:02:45.000000', NULL, 1),
(5412382, 778148, 98141, '<td valign="top">I like this a lot, the softness of it, the colors, the all-natural, woodsy feel to it.</td>', 'I like this a lot, the softness of it, the colors, the all-natural, woodsy feel to it.', '2009-04-01 13:04:20.000000', NULL, 1),
(5412384, 777124, 98141, '<td valign="top">This is an interesting backdrop for the flowers, something I haven''t seen yet in this challenge, so points for creativity.</td>', 'This is an interesting backdrop for the flowers, something I haven''t seen yet in this challenge, so points for creativity.', '2009-04-01 13:05:05.000000', NULL, 1),
(5412385, 777957, 98141, '<td valign="top">I love shots like this, great job with the lighting and the dof is nice, great greens.</td>', 'I love shots like this, great job with the lighting and the dof is nice, great greens.', '2009-04-01 13:05:40.000000', NULL, 1),
(5412386, 777173, 98141, '<td valign="top">Yellow indeed. The black background looks great, I think the contrast could go up a little or something, maybe saturation?</td>', 'Yellow indeed. The black background looks great, I think the contrast could go up a little or something, maybe saturation?', '2009-04-01 13:06:25.000000', NULL, 1),
(5412405, 777997, 98141, '<td valign="top">Nice square frame, great tilt shot. Wonderful use of dof control, the flower and gravel have great texture and the color pops against the background.</td>', 'Nice square frame, great tilt shot. Wonderful use of dof control, the flower and gravel have great texture and the color pops against the background.', '2009-04-01 13:15:02.000000', NULL, 1),
