(5415705, 777363, 26001, '<td valign="top">i like the concept. cool!</td>', 'i like the concept. cool!', '2009-04-02 20:33:07.000000', NULL, 1),
(5415707, 778270, 26001, '<td valign="top">one of the bests in the show! would have liked just a bit more light on the tree but still that doesnt stop me from awarding 10</td>', 'one of the bests in the show! would have liked just a bit more light on the tree but still that doesnt stop me from awarding 10', '2009-04-02 20:33:48.000000', NULL, 1),
(5415788, 777295, 101492, '<td valign="top">Needs a focal point.  Would make interesting background.</td>', 'Needs a focal point.  Would make interesting background.', '2009-04-02 21:22:37.000000', NULL, 1),
(5415792, 777530, 101492, '<td valign="top">I love the texture and the perspective here.  9</td>', 'I love the texture and the perspective here.  9', '2009-04-02 21:24:37.000000', NULL, 1),
(5415793, 777036, 101492, '<td valign="top">This is really well-composed and interesting.  Lighting seems a little harsh, though.</td>', 'This is really well-composed and interesting.  Lighting seems a little harsh, though.', '2009-04-02 21:26:07.000000', NULL, 1),
(5415798, 777222, 77724, '<td valign="top">I don''t think it needs the border</td>', 'I don''t think it needs the border', '2009-04-02 21:28:36.000000', NULL, 1),
(5415806, 778479, 101492, '<td valign="top">Looks very painterly.  Could be a watercolor.</td>', 'Looks very painterly.  Could be a watercolor.', '2009-04-02 21:32:37.000000', NULL, 1),
(5415811, 776834, 101492, '<td valign="top">I would love to see a crop of the big one facing forward.  Love this anyway.  8</td>', 'I would love to see a crop of the big one facing forward.  Love this anyway.  8', '2009-04-02 21:35:09.000000', NULL, 1),
(5415828, 777227, 101492, '<td valign="top">Nice clarity on the detail.</td>', 'Nice clarity on the detail.', '2009-04-02 21:42:56.000000', NULL, 1),
(5415835, 778175, 105115, '<td valign="top">Great job as usual. Love the water drops.</td>', 'Great job as usual. Love the water drops.', '2009-04-02 21:45:14.000000', NULL, 1),
(5415844, 778320, 101492, '<td valign="top">Going in my favorites!  Love it. Great color.  Great perspective.  Great lighting.  Absolutely beautiful.  10</td>', 'Going in my favorites!  Love it. Great color.  Great perspective.  Great lighting.  Absolutely beautiful.  10', '2009-04-02 21:46:19.000000', NULL, 1),
(5415887, 778307, 101492, '<td valign="top">Gorgeous image!  10  I hope you will offer this as a print.</td>', 'Gorgeous image!  10  I hope you will offer this as a print.', '2009-04-02 22:06:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5415894, 778590, 101492, '<td valign="top">Breath-taking, flower seems to glow.</td>', 'Breath-taking, flower seems to glow.', '2009-04-02 22:08:56.000000', NULL, 1),
(5415903, 777904, 76598, '<td valign="top">Love you flower, I think you need a shallower depth of field to blur the background a little more</td>', 'Love you flower, I think you need a shallower depth of field to blur the background a little more', '2009-04-02 22:13:23.000000', NULL, 1),
(5415934, 776840, 76598, '<td valign="top">Great depth of field, this little bugger can move in the wind easily</td>', 'Great depth of field, this little bugger can move in the wind easily', '2009-04-02 22:24:28.000000', NULL, 1),
(5415942, 778383, 101256, '<td valign="top">Kind of abstract in concept - creative use of DOF in a short focal length.</td>', 'Kind of abstract in concept - creative use of DOF in a short focal length.', '2009-04-02 22:35:03.000000', NULL, 1),
(5415943, 777947, 101256, '<td valign="top">Nice focus, but not particularly interesting - nothing to really attract the eye and say wow.</td>', 'Nice focus, but not particularly interesting - nothing to really attract the eye and say wow.', '2009-04-02 22:36:00.000000', NULL, 1),
(5415944, 778278, 101256, '<td valign="top">If this was recomposed, it might be a better idea to use a macro lens or adaptor to focus more on the bud - it''s lost with the oddball DOF.</td>', 'If this was recomposed, it might be a better idea to use a macro lens or adaptor to focus more on the bud - it''s lost with the oddball DOF.', '2009-04-02 22:37:00.000000', NULL, 1),
(5415947, 777741, 101256, '<td valign="top">Colors are way over saturated - it''s just a mass of color with no character and white blooms.</td>', 'Colors are way over saturated - it''s just a mass of color with no character and white blooms.', '2009-04-02 22:37:39.000000', NULL, 1),
(5415957, 777971, 101256, '<td valign="top">Too busy and DOF problems.</td>', 'Too busy and DOF problems.', '2009-04-02 22:39:29.000000', NULL, 1),
(5415961, 778319, 101256, '<td valign="top">Nice touch on the grainy effect - the slightly soft focus makes it intriguing.</td>', 'Nice touch on the grainy effect - the slightly soft focus makes it intriguing.', '2009-04-02 22:40:16.000000', NULL, 1),
(5415964, 778506, 101256, '<td valign="top">Rich detail and effective use of DOF, but it suffers from the top and side cut off. Might have done better to back off and work with the entire flower keeping the detail and DOF.</td>', 'Rich detail and effective use of DOF, but it suffers from the top and side cut off. Might have done better to back off and work with the entire flower keeping the detail and DOF.', '2009-04-02 22:41:28.000000', NULL, 1),
(5415966, 778536, 101256, '<td valign="top">Simply perfect. Wonderful back lit scene.</td>', 'Simply perfect. Wonderful back lit scene.', '2009-04-02 22:42:27.000000', NULL, 1),
(5415967, 777285, 101256, '<td valign="top">A little too subtle tone and overly dark. Odd crop is distracting.</td>', 'A little too subtle tone and overly dark. Odd crop is distracting.', '2009-04-02 22:43:13.000000', NULL, 1),
(5415970, 777621, 101256, '<td valign="top">Nice composition - sufficient bokeh, but with viewable details - a little tight on the crop, but not enough to detract from the overall impact of the image. Well done.</td>', 'Nice composition - sufficient bokeh, but with viewable details - a little tight on the crop, but not enough to detract from the overall impact of the image. Well done.', '2009-04-02 22:44:27.000000', NULL, 1),
(5415971, 778353, 101256, '<td valign="top">I might have cropped a little off the top and bottom to make the subject more definitive, but thats me.  Well done.</td>', 'I might have cropped a little off the top and bottom to make the subject more definitive, but thats me.  Well done.', '2009-04-02 22:45:21.000000', NULL, 1),
(5415972, 777954, 101256, '<td valign="top">The details of the stems disappear which is unfortunate because otherwise, this is terrific.</td>', 'The details of the stems disappear which is unfortunate because otherwise, this is terrific.', '2009-04-02 22:45:57.000000', NULL, 1),
(5415977, 777402, 101256, '<td valign="top">Green is one of the most difficult colors to deal with effectively in the digital world.  This is one of the most beautiful images where green is the predominant color I''ve ever seen anywhere. Clear, detailed with subtle tone changes. Brilliant composition - well done.</td>', 'Green is one of the most difficult colors to deal with effectively in the digital world.  This is one of the most beautiful images where green is the predominant color I''ve ever seen anywhere. Clear, detailed with subtle tone changes. Brilliant composition - well done.', '2009-04-02 22:49:01.000000', NULL, 1),
(5415978, 777736, 101256, '<td valign="top">Nice soft focus, effective DOF and excellant lighting - well done.</td>', 'Nice soft focus, effective DOF and excellant lighting - well done.', '2009-04-02 22:49:54.000000', NULL, 1),
(5415982, 778074, 101256, '<td valign="top">Another green image that is very well done.  The highlights are understated which is unusual with totally green images. The lighting helped this image a lot in my opinion.  Well done.</td>', 'Another green image that is very well done.  The highlights are understated which is unusual with totally green images. The lighting helped this image a lot in my opinion.  Well done.', '2009-04-02 22:51:45.000000', NULL, 1),
(5415984, 778622, 101256, '<td valign="top">Perfect lighting, perfect saturation, perfect composition - in short, a perfect image.  Well done.</td>', 'Perfect lighting, perfect saturation, perfect composition - in short, a perfect image.  Well done.', '2009-04-02 22:52:43.000000', NULL, 1),
(5415989, 778624, 101256, '<td valign="top">I should disqualify myself from voting on this because if I could, I''d rate it 10+. Simple and elegant with a subtle blend of color.</td>', 'I should disqualify myself from voting on this because if I could, I''d rate it 10+. Simple and elegant with a subtle blend of color.', '2009-04-02 22:54:08.000000', NULL, 1),
(5415991, 778187, 101256, '<td valign="top">Turn down the white and maybe use a curves control to adjust the just on the edge blooming white and this would be perfect and have much more impact. Nice composition and just shy on execution.</td>', 'Turn down the white and maybe use a curves control to adjust the just on the edge blooming white and this would be perfect and have much more impact. Nice composition and just shy on execution.', '2009-04-02 22:55:37.000000', NULL, 1),
(5415994, 778473, 101256, '<td valign="top">Its hard to convey a sense of color with black and white, but this manages it well.  The soft subtle tone and efficient lighting makes this image a great one.</td>', 'Its hard to convey a sense of color with black and white, but this manages it well.  The soft subtle tone and efficient lighting makes this image a great one.', '2009-04-02 22:56:49.000000', NULL, 1),
(5415995, 777363, 101256, '<td valign="top">Perfect. Excellant composition - pro quality art.</td>', 'Perfect. Excellant composition - pro quality art.', '2009-04-02 22:57:19.000000', NULL, 1),
(5415998, 777930, 101256, '<td valign="top">Very clever and worthy of a 10 just for being inventive and using the creative process to capture a terrific image never mind the technical perfection. This is wonderful.</td>', 'Very clever and worthy of a 10 just for being inventive and using the creative process to capture a terrific image never mind the technical perfection. This is wonderful.', '2009-04-02 22:58:35.000000', NULL, 1),
(5416000, 778211, 101256, '<td valign="top">Excellant - the curves and color details are outstanding.</td>', 'Excellant - the curves and color details are outstanding.', '2009-04-02 22:59:19.000000', NULL, 1),
(5416004, 777124, 101256, '<td valign="top">Very ingenious - rich in detail and clever is execution. Well done.</td>', 'Very ingenious - rich in detail and clever is execution. Well done.', '2009-04-02 23:00:46.000000', NULL, 1),
(5416008, 777447, 101256, '<td valign="top">This image suffers from a sizing problem - if it were larger, it would be a good candidate for different and unique.</td>', 'This image suffers from a sizing problem - if it were larger, it would be a good candidate for different and unique.', '2009-04-02 23:01:52.000000', NULL, 1),
(5416009, 778366, 101256, '<td valign="top">Elegant simplicity.</td>', 'Elegant simplicity.', '2009-04-02 23:02:08.000000', NULL, 1),
(5416011, 778409, 101256, '<td valign="top">Too much frame and not enough image.</td>', 'Too much frame and not enough image.', '2009-04-02 23:02:32.000000', NULL, 1),
(5416015, 778044, 101256, '<td valign="top">This would have worked if you had waited a few minutes for the sun to reach the horizon - I believe you used a flash with highlighted the wrong area. A little patience would have improved this image a hundred fold.</td>', 'This would have worked if you had waited a few minutes for the sun to reach the horizon - I believe you used a flash with highlighted the wrong area. A little patience would have improved this image a hundred fold.', '2009-04-02 23:06:20.000000', NULL, 1),
(5416020, 778672, 24073, '<td valign="top">Some of you guys make it looks so easy.  Do you know when you enter this that it will be hard to beat?<br/> <br/>Alright so anyway...great shot, if not a little cocky with the skills you posess.  Color-fantastic, composition-solid, mood-A+...is there one reason whatsoever I shouldn''t vote this a 10?, not really, but I''m given ya an 8 till the end, and I''ll see how ya stand up amongst the crowd.  Great job.\<br/> <br/>...bumping to 9.</td>', 'Some of you guys make it looks so easy.  Do you know when you enter this that it will be hard to beat? Alright so anyway...great shot, if not a little cocky with the skills you posess.  Color-fantastic, composition-solid, mood-A+...is there one reason whatsoever I shouldn''t vote this a 10?, not really, but I''m given ya an 8 till the end, and I''ll see how ya stand up amongst the crowd.  Great job.\ ...bumping to 9.', '2009-04-02 23:08:20.000000', NULL, 1),
(5416027, 778672, 101256, '<td valign="top">A composite image that is ineffective, manufactured and unnatural. As a political themed image it might work, but as a image of natural flora, it fails.</td>', 'A composite image that is ineffective, manufactured and unnatural. As a political themed image it might work, but as a image of natural flora, it fails.', '2009-04-02 23:11:07.000000', NULL, 1),
(5416031, 777031, 101256, '<td valign="top">Gorgeous - simple and very subtle.</td>', 'Gorgeous - simple and very subtle.', '2009-04-02 23:12:52.000000', NULL, 1),
(5416036, 777030, 101256, '<td valign="top">Unusual in that everything is in focus with rich details which invite the eye to explore further.  Well done.</td>', 'Unusual in that everything is in focus with rich details which invite the eye to explore further.  Well done.', '2009-04-02 23:13:42.000000', NULL, 1),
(5416043, 778421, 101256, '<td valign="top">The color washes out the detail on the left side of the flower which is distracting, but not sufficiently to effect my rating - this is a great composition aptly named and very inventive.  Nice.</td>', 'The color washes out the detail on the left side of the flower which is distracting, but not sufficiently to effect my rating - this is a great composition aptly named and very inventive.  Nice.', '2009-04-02 23:16:10.000000', NULL, 1),
(5416046, 778675, 101256, '<td valign="top">Perfect - excellant detail, solid and effective bokeh with just enough detail to make it interesting - great image.</td>', 'Perfect - excellant detail, solid and effective bokeh with just enough detail to make it interesting - great image.', '2009-04-02 23:17:14.000000', NULL, 1),
(5416050, 778270, 101256, '<td valign="top">I like this if only because of the inspired use of light for effect. The background helps, but is not overly imposing on the image.</td>', 'I like this if only because of the inspired use of light for effect. The background helps, but is not overly imposing on the image.', '2009-04-02 23:18:30.000000', NULL, 1),
(5416051, 778187, 24073, '<td valign="top">My top 1.  Great, great job.  Love the tones, and mood it sets.  A beautiful addition to anybodys home wall.</td>', 'My top 1.  Great, great job.  Love the tones, and mood it sets.  A beautiful addition to anybodys home wall.', '2009-04-02 23:19:10.000000', NULL, 1),
(5416053, 778575, 24073, '<td valign="top">Quite simple, and very effective. In my top 10.</td>', 'Quite simple, and very effective. In my top 10.', '2009-04-02 23:20:16.000000', NULL, 1),
(5416056, 777981, 24073, '<td valign="top">Well I love it, but I''m not sure if everybody else will.  If it were up to me I''d finish ya in the top 10.  Great job.</td>', 'Well I love it, but I''m not sure if everybody else will.  If it were up to me I''d finish ya in the top 10.  Great job.', '2009-04-02 23:21:27.000000', NULL, 1),
(5416059, 778362, 24073, '<td valign="top">sweet looking bokeh, the best I''ve seen.  I''m wondering if the orientation isn''t too strait, and boring.  I personally would of liked to see it coming in off a slant, i dunno though, second look, and its growing on me.<br/> <br/>...I''m back to bump ^, fantastic use of color.  You should finish strong, it has a stand out appeal.</td>', 'sweet looking bokeh, the best I''ve seen.  I''m wondering if the orientation isn''t too strait, and boring.  I personally would of liked to see it coming in off a slant, i dunno though, second look, and its growing on me. ...I''m back to bump ^, fantastic use of color.  You should finish strong, it has a stand out appeal.', '2009-04-02 23:23:10.000000', NULL, 1),
(5416100, 778518, 89223, '<td valign="top">you set the scene very well here, Beautiful photo, i love the over hanging leafs, very nice!</td>', 'you set the scene very well here, Beautiful photo, i love the over hanging leafs, very nice!', '2009-04-02 23:43:25.000000', NULL, 1),
(5416108, 778309, 89223, '<td valign="top">i think the color contrast here is great, and i love the vibrance of the colors, i think the only thing i really dont like is the pink in the bottem right corner, i feel if that was removed, and you could see more of the green, that it would bring a lot more to this photo.</td>', 'i think the color contrast here is great, and i love the vibrance of the colors, i think the only thing i really dont like is the pink in the bottem right corner, i feel if that was removed, and you could see more of the green, that it would bring a lot more to this photo.', '2009-04-02 23:49:43.000000', NULL, 1),
(5416186, 778588, 105119, '<td valign="top">Beautiful Picture this has to be one of my favorite pictures!<br/> <br/>Great Job</td>', 'Beautiful Picture this has to be one of my favorite pictures! Great Job', '2009-04-03 00:47:07.000000', NULL, 1),
(5416187, 777954, 57913, '<td valign="top">Nice macro work!  The colors are good and the details are amazing.</td>', 'Nice macro work!  The colors are good and the details are amazing.', '2009-04-03 00:47:15.000000', NULL, 1),
(5416189, 778590, 105119, '<td valign="top">Beautiful picture!</td>', 'Beautiful picture!', '2009-04-03 00:47:34.000000', NULL, 1),
(5416285, 777030, 15407, '<td valign="top">VERY NICE!</td>', 'VERY NICE!', '2009-04-03 02:09:13.000000', NULL, 1),
(5416294, 777363, 15407, '<td valign="top">Nice work here!</td>', 'Nice work here!', '2009-04-03 02:18:21.000000', NULL, 1),
(5416315, 778575, 15407, '<td valign="top">WOW! You''ve made this great photo tough for me to judge! Great Colors, composistion, the bokeh, and nearly perfect... the wind always plays havoc with Poppies... yet the very narrow focus distracts... better than any that I have been able to do with wind bow poppeis.. can''t give it any less than a 8 and that''s because a lesser ''frame''would have made it a 7.</td>', 'WOW! You''ve made this great photo tough for me to judge! Great Colors, composistion, the bokeh, and nearly perfect... the wind always plays havoc with Poppies... yet the very narrow focus distracts... better than any that I have been able to do with wind bow poppeis.. can''t give it any less than a 8 and that''s because a lesser ''frame''would have made it a 7.', '2009-04-03 02:34:28.000000', NULL, 1),
(5416322, 777773, 15407, '<td valign="top">Subject is waterfall in this photo not flora</td>', 'Subject is waterfall in this photo not flora', '2009-04-03 02:41:22.000000', NULL, 1),
(5416324, 778074, 15407, '<td valign="top">Great photo. I really like the focus &amp; bokeh!</td>', 'Great photo. I really like the focus & bokeh!', '2009-04-03 02:42:18.000000', NULL, 1),
(5416335, 777812, 15407, '<td valign="top">This maeme laugh!!!  I''m deathly allergic to Tomatoes... so it''s with great pleasure I can vote your entry high without prejudice!</td>', 'This maeme laugh!!!  I''m deathly allergic to Tomatoes... so it''s with great pleasure I can vote your entry high without prejudice!', '2009-04-03 02:55:39.000000', NULL, 1),
(5416340, 777621, 15407, '<td valign="top">Looks like a cleaver photo of a waterfall in the background... sorry if it isn''t!</td>', 'Looks like a cleaver photo of a waterfall in the background... sorry if it isn''t!', '2009-04-03 03:01:15.000000', NULL, 1),
(5416343, 778518, 15407, '<td valign="top">The photo tells the story, NOT the title.</td>', 'The photo tells the story, NOT the title.', '2009-04-03 03:04:21.000000', NULL, 1),
(5416344, 777949, 15407, '<td valign="top">Great use of DOF.</td>', 'Great use of DOF.', '2009-04-03 03:05:01.000000', NULL, 1),
(5416346, 778226, 15407, '<td valign="top">1967 San Francisco! I was there too...</td>', '1967 San Francisco! I was there too...', '2009-04-03 03:09:25.000000', NULL, 1),
(5416347, 777254, 15407, '<td valign="top">WAY to much water ! -1</td>', 'WAY to much water ! -1', '2009-04-03 03:10:21.000000', NULL, 1),
(5416352, 778575, 93421, '<td valign="top">Stunning!  The colours here are great</td>', 'Stunning!  The colours here are great', '2009-04-03 03:20:09.000000', NULL, 1),
(5416437, 778575, 51538, '<td valign="top">Nice bokeh on this one.</td>', 'Nice bokeh on this one.', '2009-04-03 07:48:56.000000', NULL, 1),
(5416438, 778409, 51538, '<td valign="top">This is all about the frame.  The photo is rather secondary.  I like the symmetry.</td>', 'This is all about the frame.  The photo is rather secondary.  I like the symmetry.', '2009-04-03 07:54:00.000000', NULL, 1),
(5416451, 777019, 101256, '<td valign="top">I think this would have been much better is you had concentrated on the stalks to the right foreground - there is too much color blending in the middle making the very interesting scene disappear into the bokeh. The simplicity and elegance is lost.</td>', 'I think this would have been much better is you had concentrated on the stalks to the right foreground - there is too much color blending in the middle making the very interesting scene disappear into the bokeh. The simplicity and elegance is lost.', '2009-04-03 08:34:54.000000', NULL, 1),
(5416453, 778434, 101256, '<td valign="top">I like this, but again, another image that needs a good crop to bring out the very interesting features in the middle of the water drop. Everything else in this image is a side show and detracts from the overall surrealist impression.</td>', 'I like this, but again, another image that needs a good crop to bring out the very interesting features in the middle of the water drop. Everything else in this image is a side show and detracts from the overall surrealist impression.', '2009-04-03 08:36:41.000000', NULL, 1),
(5416455, 777943, 101256, '<td valign="top">The DOF control is excellant and from a technical standpoint, the image is very well done.  However it is incredibly uninteresting and dull. A higher angle to address more of the face of the dandelion would have helped a lot.</td>', 'The DOF control is excellant and from a technical standpoint, the image is very well done.  However it is incredibly uninteresting and dull. A higher angle to address more of the face of the dandelion would have helped a lot.', '2009-04-03 08:38:17.000000', NULL, 1),
(5416458, 778263, 101256, '<td valign="top">I''m ambivalent about this - on the one hand, it''s very intriguing - the rather interesting color cast and detail are a curiosity - on the other, the right hand DOF is distracting and unbalances the image from its central focus. Eh - split the difference between the two.</td>', 'I''m ambivalent about this - on the one hand, it''s very intriguing - the rather interesting color cast and detail are a curiosity - on the other, the right hand DOF is distracting and unbalances the image from its central focus. Eh - split the difference between the two.', '2009-04-03 08:41:28.000000', NULL, 1),
(5416460, 777730, 101256, '<td valign="top">A tad over done on the lighting - it would be much better with a faster shutter speed or a little more deft hand with the aperature. The unfortunate part is the white bloom on the lower bud and poor crop.  Even with the white bloom, it would have worked very well without the stem.</td>', 'A tad over done on the lighting - it would be much better with a faster shutter speed or a little more deft hand with the aperature. The unfortunate part is the white bloom on the lower bud and poor crop.  Even with the white bloom, it would have worked very well without the stem.', '2009-04-03 08:43:27.000000', NULL, 1),
(5416461, 778572, 101256, '<td valign="top">Excellant combination of flora and fauna - really like the idea here. Unfortunately, the DOF on the leaf ruins the overall effort.  A+ for concept, A for composition, C- for execution.</td>', 'Excellant combination of flora and fauna - really like the idea here. Unfortunately, the DOF on the leaf ruins the overall effort.  A+ for concept, A for composition, C- for execution.', '2009-04-03 08:44:51.000000', NULL, 1),
(5416462, 777737, 101256, '<td valign="top">Simply elegant - minimalist in execution. Minor foreground grain problem - very well executed with minor flaw.</td>', 'Simply elegant - minimalist in execution. Minor foreground grain problem - very well executed with minor flaw.', '2009-04-03 08:45:44.000000', NULL, 1),
(5416464, 777511, 101256, '<td valign="top">Focus problem which hurts the image. Would have been a better image if the author had backed off a little.</td>', 'Focus problem which hurts the image. Would have been a better image if the author had backed off a little.', '2009-04-03 08:46:40.000000', NULL, 1),
(5416467, 777810, 101256, '<td valign="top">Over saturated and over sharpened. It almost looks like a composite image with the flowers added in to the background.</td>', 'Over saturated and over sharpened. It almost looks like a composite image with the flowers added in to the background.', '2009-04-03 08:48:40.000000', NULL, 1),
(5416498, 778581, 101256, '<td valign="top">The overdone edge whites are distracting - the sharp devolution from yellow to blue isn''t the best transition making the image look over sharpened ever though it isn''t.</td>', 'The overdone edge whites are distracting - the sharp devolution from yellow to blue isn''t the best transition making the image look over sharpened ever though it isn''t.', '2009-04-03 09:10:45.000000', NULL, 1),
(5416502, 777364, 101256, '<td valign="top">This would have been a great image if the DOF had been kept under control. It''s also ever so slightly out of focus which also hurts.</td>', 'This would have been a great image if the DOF had been kept under control. It''s also ever so slightly out of focus which also hurts.', '2009-04-03 09:11:44.000000', NULL, 1),
(5416504, 778492, 101256, '<td valign="top">A touch over sharpened and the DOF control, which is very important in these types of images doesn''t work.</td>', 'A touch over sharpened and the DOF control, which is very important in these types of images doesn''t work.', '2009-04-03 09:13:08.000000', NULL, 1),
(5416517, 778642, 101256, '<td valign="top">Interesting image, but the lighting did it no favors at all. The odd whites here and there overly complicate an already complex image. It might have been better to concentrate on just one section and work with that rather than try to capture the entire busy scene.</td>', 'Interesting image, but the lighting did it no favors at all. The odd whites here and there overly complicate an already complex image. It might have been better to concentrate on just one section and work with that rather than try to capture the entire busy scene.', '2009-04-03 09:17:09.000000', NULL, 1),
(5416518, 777036, 101256, '<td valign="top">Foreground complimenting the background - check. Detail - check. Above average use of light in composing - check. Color saturation not over done - check.  Well done.</td>', 'Foreground complimenting the background - check. Detail - check. Above average use of light in composing - check. Color saturation not over done - check.  Well done.', '2009-04-03 09:18:27.000000', NULL, 1),
(5416520, 777812, 101256, '<td valign="top">I''m rating it higher, even though its a staged image, just because it really funny - laugh out loud funny.</td>', 'I''m rating it higher, even though its a staged image, just because it really funny - laugh out loud funny.', '2009-04-03 09:19:43.000000', NULL, 1),
(5416521, 778621, 101256, '<td valign="top">A very unique perspective leading the eye to either take this as a vertical image or a horizontal image. Might have done better centering the subject rather than having it offset which would have enhanced the illusion. Very nice.</td>', 'A very unique perspective leading the eye to either take this as a vertical image or a horizontal image. Might have done better centering the subject rather than having it offset which would have enhanced the illusion. Very nice.', '2009-04-03 09:20:56.000000', NULL, 1),
(5416523, 778212, 101256, '<td valign="top">Very well executed - exquisite and simple. Well done.</td>', 'Very well executed - exquisite and simple. Well done.', '2009-04-03 09:23:32.000000', NULL, 1),
(5416526, 777295, 101256, '<td valign="top">This might work as a shower curtain, but as a fauna image, its much to busy and over wrought. There is a lot of meaningless shapes and the monotone coloration just makes it boring.</td>', 'This might work as a shower curtain, but as a fauna image, its much to busy and over wrought. There is a lot of meaningless shapes and the monotone coloration just makes it boring.', '2009-04-03 09:24:52.000000', NULL, 1),
(5416527, 778424, 63499, '<td valign="top">I don''t think I''ve ever seen an aloe plant in bloom before - it''s very pretty! I like the colors and the composition, I just wish the DOF wasn''t quite so narrow.</td>', 'I don''t think I''ve ever seen an aloe plant in bloom before - it''s very pretty! I like the colors and the composition, I just wish the DOF wasn''t quite so narrow.', '2009-04-03 09:25:19.000000', NULL, 1),
(5416528, 778252, 101256, '<td valign="top">This would have worked very well if the DOF was properly executed. A great concept poorly executed - it would have scored well if properly composed.</td>', 'This would have worked very well if the DOF was properly executed. A great concept poorly executed - it would have scored well if properly composed.', '2009-04-03 09:25:53.000000', NULL, 1),
(5416529, 777970, 101256, '<td valign="top">It certainly is a botanical abstract and it is excellant.  Well done.</td>', 'It certainly is a botanical abstract and it is excellant.  Well done.', '2009-04-03 09:26:25.000000', NULL, 1),
(5416532, 778533, 101256, '<td valign="top">I wasn''t sure if it was my glasses, my monitor or I was having another episode with eye fatique. I understand what the author was trying to pull off here, but it doesn''t work - something has to be focused or on the other hand, unfocused to create the etheral image the title suggests.</td>', 'I wasn''t sure if it was my glasses, my monitor or I was having another episode with eye fatique. I understand what the author was trying to pull off here, but it doesn''t work - something has to be focused or on the other hand, unfocused to create the etheral image the title suggests.', '2009-04-03 09:28:23.000000', NULL, 1),
(5416533, 777536, 101256, '<td valign="top">Almost like a fire flame and the interesting right on the edge of over done white is a very nice touch - accidental or not.</td>', 'Almost like a fire flame and the interesting right on the edge of over done white is a very nice touch - accidental or not.', '2009-04-03 09:29:41.000000', NULL, 1),
(5416534, 776834, 88926, '<td valign="top">I like the back lighting it brings out the colors in the petals very well. The saturation, brightness/contrast and focus are all spot on.</td>', 'I like the back lighting it brings out the colors in the petals very well. The saturation, brightness/contrast and focus are all spot on.', '2009-04-03 09:30:24.000000', NULL, 1),
(5416535, 777577, 101256, '<td valign="top">If there were one image that could have done with HDR treatment, this would have been one of them.  As it is, it''s a very dramatic image that is slightly underdone.  A little more time composing and a little more effort with bringing out the dramatic sky in post processing would have made this a winner.</td>', 'If there were one image that could have done with HDR treatment, this would have been one of them.  As it is, it''s a very dramatic image that is slightly underdone.  A little more time composing and a little more effort with bringing out the dramatic sky in post processing would have made this a winner.', '2009-04-03 09:31:08.000000', NULL, 1),
(5416538, 777530, 101256, '<td valign="top">You know what would have been a great title for this? Wormhole. A perfect image - excellant color and DOF control, excellant detail - all around a great image - I''m jealous I didn''t think of it.</td>', 'You know what would have been a great title for this? Wormhole. A perfect image - excellant color and DOF control, excellant detail - all around a great image - I''m jealous I didn''t think of it.', '2009-04-03 09:33:33.000000', NULL, 1),
(5416539, 778514, 101256, '<td valign="top">A great example of how to control DOF and a offset properly focused and controlled subject - it could very well be used as an illustrativve entry in a how to section photography book.  Well done.</td>', 'A great example of how to control DOF and a offset properly focused and controlled subject - it could very well be used as an illustrativve entry in a how to section photography book.  Well done.', '2009-04-03 09:34:31.000000', NULL, 1),
(5416540, 776597, 101256, '<td valign="top">A good set piece and suitable for a landscaping magazine cover. Nicely composed and executed - not perfect by any means, but good none the less.</td>', 'A good set piece and suitable for a landscaping magazine cover. Nicely composed and executed - not perfect by any means, but good none the less.', '2009-04-03 09:35:14.000000', NULL, 1),
(5416549, 776810, 101256, '<td valign="top">I believe that the offset in this image is overdone and is a negative because of the sharp cutoff.  Might have been better to back off the image and get a more complete subject.</td>', 'I believe that the offset in this image is overdone and is a negative because of the sharp cutoff.  Might have been better to back off the image and get a more complete subject.', '2009-04-03 09:49:19.000000', NULL, 1),
(5416554, 778437, 101256, '<td valign="top">Flora and fauna together in one - that should be another challenge.  :&gt;) Interesting shot - the detail is nicely accomplished but I don''t have a special feeling for this image. Technically, it''s fine, emotionally - eh.</td>', 'Flora and fauna together in one - that should be another challenge.  :>) Interesting shot - the detail is nicely accomplished but I don''t have a special feeling for this image. Technically, it''s fine, emotionally - eh.', '2009-04-03 09:51:00.000000', NULL, 1),
(5416557, 777928, 101256, '<td valign="top">A good example when the DOF is not properly controlled. If the bud and upper part of the stem had been completely in focus, this would have worked very well against the background. A simple fade of the stem would have improved this image tremendously.</td>', 'A good example when the DOF is not properly controlled. If the bud and upper part of the stem had been completely in focus, this would have worked very well against the background. A simple fade of the stem would have improved this image tremendously.', '2009-04-03 09:52:32.000000', NULL, 1),
(5416560, 777902, 101256, '<td valign="top">Wow!! Terrific image - clever and inventive - very effective from a visual standpoint.  It feels staged, but who cares - nicely done.</td>', 'Wow!! Terrific image - clever and inventive - very effective from a visual standpoint.  It feels staged, but who cares - nicely done.', '2009-04-03 09:53:46.000000', NULL, 1),
(5416562, 777771, 101256, '<td valign="top">Perfect use of offset space alng with clear and detailed subject - very effective.</td>', 'Perfect use of offset space alng with clear and detailed subject - very effective.', '2009-04-03 09:54:23.000000', NULL, 1),
(5416564, 778640, 101256, '<td valign="top">This image could have gone horribly wrong - I mean horribly wrong. :&gt;)<br/> <br/>Fortunately, everything went right - it''s a great image of a simple flower. Beautiful in it''s simplicity. It deserves to place well.</td>', 'This image could have gone horribly wrong - I mean horribly wrong. :>) Fortunately, everything went right - it''s a great image of a simple flower. Beautiful in it''s simplicity. It deserves to place well.', '2009-04-03 09:55:42.000000', NULL, 1),
(5416571, 778325, 101256, '<td valign="top">The unfocused effect works in this image because it feels like an unforced error. It''s a gentle fade that works well. The subject matter is dull and uninteresting, but from a technical standpoint, its a good image.</td>', 'The unfocused effect works in this image because it feels like an unforced error. It''s a gentle fade that works well. The subject matter is dull and uninteresting, but from a technical standpoint, its a good image.', '2009-04-03 09:57:13.000000', NULL, 1),
(5416610, 778230, 101256, '<td valign="top">The major problem with this image is the over sharpening effect.  I don''t believe it was over sharpened because the halo effect that is the primary indicator of over sharpened doesn''t carry through from the right side of the hand to the top of the image - meaning that it''s a lighting problem - what I''m seeing is the surface vein blood of the skin reflecting against the black background. This might have worked much better with a gray background or lighter shade of black.</td>', 'The major problem with this image is the over sharpening effect.  I don''t believe it was over sharpened because the halo effect that is the primary indicator of over sharpened doesn''t carry through from the right side of the hand to the top of the image - meaning that it''s a lighting problem - what I''m seeing is the surface vein blood of the skin reflecting against the black background. This might have worked much better with a gray background or lighter shade of black.', '2009-04-03 10:10:15.000000', NULL, 1),
(5416612, 778465, 101256, '<td valign="top">The blurred central portion of this centered image is very unfortunate because its a great composition in many other ways. Better lens and apperature control would have made it a excellant image.</td>', 'The blurred central portion of this centered image is very unfortunate because its a great composition in many other ways. Better lens and apperature control would have made it a excellant image.', '2009-04-03 10:11:29.000000', NULL, 1),
(5416615, 777700, 101256, '<td valign="top">Right on the edge of being a snapshot quality image, but the soft focus helped it - hopefully by design. Not overly interesting, but effective as a casual candid.</td>', 'Right on the edge of being a snapshot quality image, but the soft focus helped it - hopefully by design. Not overly interesting, but effective as a casual candid.', '2009-04-03 10:13:04.000000', NULL, 1),
(5416622, 777690, 101256, '<td valign="top">Great concept unfortunately the flowers don''t have enough color or are as interesting as the city in the background. There is also a focusing problem - the image isn''t as sharp as it should be. A good effort though just lacking in execution.</td>', 'Great concept unfortunately the flowers don''t have enough color or are as interesting as the city in the background. There is also a focusing problem - the image isn''t as sharp as it should be. A good effort though just lacking in execution.', '2009-04-03 10:17:28.000000', NULL, 1),
(5416626, 777222, 101256, '<td valign="top">I think this would have worked much better with a half window crop and sharper focus and aperature control to reduce the difference between the whites, reds and greens.</td>', 'I think this would have worked much better with a half window crop and sharper focus and aperature control to reduce the difference between the whites, reds and greens.', '2009-04-03 10:19:53.000000', NULL, 1),
(5416630, 778242, 101256, '<td valign="top">Whoa momma - yowzers this is great. Greens are very difficult with digital images and you''ve done wonders with the overall green tone and effect. The details are incredible and the slight grain in the background enhances the overall effect.  Brilliant composition and it should be one of the contenders for a blue ribbon. Can''t get over just how excellent this image is - pro quality.</td>', 'Whoa momma - yowzers this is great. Greens are very difficult with digital images and you''ve done wonders with the overall green tone and effect. The details are incredible and the slight grain in the background enhances the overall effect.  Brilliant composition and it should be one of the contenders for a blue ribbon. Can''t get over just how excellent this image is - pro quality.', '2009-04-03 10:22:06.000000', NULL, 1),
(5416633, 777416, 101256, '<td valign="top">From a technical composition perspective, this is very good use of space, color and bokeh. From a artistic standpoint - meh. Maybe a slightly different angle would have helped. Other than that, I''ve got nothing. :&gt;) Good effort though.</td>', 'From a technical composition perspective, this is very good use of space, color and bokeh. From a artistic standpoint - meh. Maybe a slightly different angle would have helped. Other than that, I''ve got nothing. :>) Good effort though.', '2009-04-03 10:24:16.000000', NULL, 1),
(5416642, 778475, 101256, '<td valign="top">Another blue ribbon contender.  It''s very difficult to capture snow crystals without blowing out pixels and the author pulled it off perfectly.  The transition from black to gray to white is perfect. If Georgia O''Keeffe had talked Alfred Stieglitz into making a photograph under her direction, this would have been the result.</td>', 'Another blue ribbon contender.  It''s very difficult to capture snow crystals without blowing out pixels and the author pulled it off perfectly.  The transition from black to gray to white is perfect. If Georgia O''Keeffe had talked Alfred Stieglitz into making a photograph under her direction, this would have been the result.', '2009-04-03 10:29:03.000000', NULL, 1),
(5416647, 778403, 101256, '<td valign="top">Very dream like with one minor flaw that I''m not even going to mention because nobody but me would notice it. The soft subtle lighting and gentle color cast are extremely evocative and pleasing to the eye. Thisis another image that has a O''Keeffe feel to it - just on the edge of being abstract without drama - romantic in a way.  Well done.</td>', 'Very dream like with one minor flaw that I''m not even going to mention because nobody but me would notice it. The soft subtle lighting and gentle color cast are extremely evocative and pleasing to the eye. Thisis another image that has a O''Keeffe feel to it - just on the edge of being abstract without drama - romantic in a way.  Well done.', '2009-04-03 10:32:17.000000', NULL, 1),
(5416651, 776450, 101256, '<td valign="top">Do bugs quality as flora or fauna? :&gt;)  A nice moody piece.  In this case, the soft focus on the leaf works, but the eye is drawn to the lady bug which is outside the context of the challenge. A nice composition, but misplaced in category.</td>', 'Do bugs quality as flora or fauna? :>)  A nice moody piece.  In this case, the soft focus on the leaf works, but the eye is drawn to the lady bug which is outside the context of the challenge. A nice composition, but misplaced in category.', '2009-04-03 10:34:07.000000', NULL, 1),
(5416652, 778462, 101256, '<td valign="top">I want to know who keeps doing these minimalist images or flowers - outstanding work.</td>', 'I want to know who keeps doing these minimalist images or flowers - outstanding work.', '2009-04-03 10:34:39.000000', NULL, 1),
(5416654, 778080, 101256, '<td valign="top">A perfect composition with a perfect title.  A worthy contender for the top prize. Rich and effective detail with all the right components of technical perfection from bokeh to foreground.</td>', 'A perfect composition with a perfect title.  A worthy contender for the top prize. Rich and effective detail with all the right components of technical perfection from bokeh to foreground.', '2009-04-03 10:35:43.000000', NULL, 1),
(5416657, 778584, 101256, '<td valign="top">I''d really like to give this a 9 or 10, but the minor shift in focus at the bottom mars an otherwise excellant image. Great use of DOF.</td>', 'I''d really like to give this a 9 or 10, but the minor shift in focus at the bottom mars an otherwise excellant image. Great use of DOF.', '2009-04-03 10:37:04.000000', NULL, 1),
(5416662, 777623, 101256, '<td valign="top">I can''t stop laughing. Outside the scope of the challenge, but its laugh out loud funny and very cleverly executed. Who cares - give it a ten for execution.</td>', 'I can''t stop laughing. Outside the scope of the challenge, but its laugh out loud funny and very cleverly executed. Who cares - give it a ten for execution.', '2009-04-03 10:38:49.000000', NULL, 1),
(5416665, 777361, 101256, '<td valign="top">A different angle to reduce the white blooms would have improved this image tremendously - the whites are too severe and detract from the overall impact of the image.</td>', 'A different angle to reduce the white blooms would have improved this image tremendously - the whites are too severe and detract from the overall impact of the image.', '2009-04-03 10:41:30.000000', NULL, 1),
(5416666, 776718, 101256, '<td valign="top">Perfect - no matter how hard I try, I can''t find a single flaw in either composition with zero technical flaws.  Very evocative and the impact is startling - it''s a wow factor image.</td>', 'Perfect - no matter how hard I try, I can''t find a single flaw in either composition with zero technical flaws.  Very evocative and the impact is startling - it''s a wow factor image.', '2009-04-03 10:43:08.000000', NULL, 1),
(5416670, 778320, 101256, '<td valign="top">The author thought the title out and the execution was perfect.  Technically excellant. The image''s overall impact and beautiful color shifts are captured effectively and efficiently.  Very pleasing to the eye.  Well done.</td>', 'The author thought the title out and the execution was perfect.  Technically excellant. The image''s overall impact and beautiful color shifts are captured effectively and efficiently.  Very pleasing to the eye.  Well done.', '2009-04-03 10:45:02.000000', NULL, 1),
(5416671, 777294, 101256, '<td valign="top">Snow and ice are extremely hard to manage technically and this image is a great example of how that can be controlled with proper lighting and composition.  Well done.</td>', 'Snow and ice are extremely hard to manage technically and this image is a great example of how that can be controlled with proper lighting and composition.  Well done.', '2009-04-03 10:45:48.000000', NULL, 1),
(5416673, 778243, 101256, '<td valign="top">Very unfortunate - the DOF is totally reversed and its a very jarring image to look at - a major flaw. At first, I thought it was shutter shake, but it appears to be intentional.</td>', 'Very unfortunate - the DOF is totally reversed and its a very jarring image to look at - a major flaw. At first, I thought it was shutter shake, but it appears to be intentional.', '2009-04-03 10:48:29.000000', NULL, 1),
(5416677, 778662, 101256, '<td valign="top">Very impressive - excellent DOF control, crips and sharp image. Interesting that the ant takes a while to resolve with the eye - you really hvae to look for it as it almost appears to be part of the flower. Interesting image.</td>', 'Very impressive - excellent DOF control, crips and sharp image. Interesting that the ant takes a while to resolve with the eye - you really hvae to look for it as it almost appears to be part of the flower. Interesting image.', '2009-04-03 10:50:12.000000', NULL, 1),
(5416681, 777410, 101256, '<td valign="top">Perfect - subtle and romantic - almost a noir image in a sense. Well done.</td>', 'Perfect - subtle and romantic - almost a noir image in a sense. Well done.', '2009-04-03 10:52:08.000000', NULL, 1),
(5416683, 777952, 101256, '<td valign="top">Another terrific use of green with subtle color shift to golden yellow. Well done.</td>', 'Another terrific use of green with subtle color shift to golden yellow. Well done.', '2009-04-03 10:52:42.000000', NULL, 1),
(5416686, 778590, 101256, '<td valign="top">A very nice offset shot. The internal lighting effect with the flower is wonderful - just on the edge of the color being blown through. Well done.</td>', 'A very nice offset shot. The internal lighting effect with the flower is wonderful - just on the edge of the color being blown through. Well done.', '2009-04-03 10:53:33.000000', NULL, 1),
(5416689, 777224, 101256, '<td valign="top">Perfect - absoutely perfect. Should be a top contender.</td>', 'Perfect - absoutely perfect. Should be a top contender.', '2009-04-03 10:55:57.000000', NULL, 1),
(5416691, 778180, 101256, '<td valign="top">Nice, but flawed. The surface tension of the water is very interesting, but the bokeh breaks up the image and detracts from the image''s effective impact.<br/>Neat idea though.</td>', 'Nice, but flawed. The surface tension of the water is very interesting, but the bokeh breaks up the image and detracts from the image''s effective impact.Neat idea though.', '2009-04-03 10:57:36.000000', NULL, 1),
(5416695, 777625, 98339, '<td valign="top">very interesting...what is this plant...great shot...</td>', 'very interesting...what is this plant...great shot...', '2009-04-03 10:59:04.000000', NULL, 1),
(5416699, 778269, 101256, '<td valign="top">This is a wonderful image - the soft yet detailed imagery is very interesting, but I''m not sure it fits within the scope of the challenge. Benefit of the doubt on this one to the author - well done.</td>', 'This is a wonderful image - the soft yet detailed imagery is very interesting, but I''m not sure it fits within the scope of the challenge. Benefit of the doubt on this one to the author - well done.', '2009-04-03 11:01:25.000000', NULL, 1),
(5416701, 777533, 101256, '<td valign="top">A nice effort, but it feels way too contrived and false - almost as if the browns were painted in place.</td>', 'A nice effort, but it feels way too contrived and false - almost as if the browns were painted in place.', '2009-04-03 11:02:45.000000', NULL, 1),
(5416702, 778226, 101256, '<td valign="top">Much too busy and the subject is lost in the background. A closer macro examination would have worked much better.</td>', 'Much too busy and the subject is lost in the background. A closer macro examination would have worked much better.', '2009-04-03 11:03:44.000000', NULL, 1),
(5416704, 777934, 101256, '<td valign="top">Gorgeous, but severely flawed.  The bottom black border is significant in how it detracts from the image and it''s overall impact on the viewer. Very unfortunate because it could have been a high score but for that.</td>', 'Gorgeous, but severely flawed.  The bottom black border is significant in how it detracts from the image and it''s overall impact on the viewer. Very unfortunate because it could have been a high score but for that.', '2009-04-03 11:05:35.000000', NULL, 1),
(5416708, 778513, 101256, '<td valign="top">Technically, everything is controlled and very well executed.  From an interest standpoint, its meaningless and uninteresting - its just another dandelion going to seed. Might have helped if there was a little action like a subtle breeze - something other than just a static shot.</td>', 'Technically, everything is controlled and very well executed.  From an interest standpoint, its meaningless and uninteresting - its just another dandelion going to seed. Might have helped if there was a little action like a subtle breeze - something other than just a static shot.', '2009-04-03 11:07:17.000000', NULL, 1),
(5416710, 777505, 101256, '<td valign="top">Too much white - the scene is over lit and the background only enhances that defect. Nice composition with unfortunate defect.</td>', 'Too much white - the scene is over lit and the background only enhances that defect. Nice composition with unfortunate defect.', '2009-04-03 11:08:20.000000', NULL, 1),
(5416713, 777684, 101256, '<td valign="top">I have to explain my vote on this one - frankly it''s way over done and has no significant features to compliment the right on the edge white bloom. This image should have been thought through more and recomposed to create some interest - there''s nothing to recommend this as even an average image.</td>', 'I have to explain my vote on this one - frankly it''s way over done and has no significant features to compliment the right on the edge white bloom. This image should have been thought through more and recomposed to create some interest - there''s nothing to recommend this as even an average image.', '2009-04-03 11:10:27.000000', NULL, 1),
(5416786, 778426, 103470, '<td valign="top">I dont get it how is this a plant or anything to do with plants??</td>', 'I dont get it how is this a plant or anything to do with plants??', '2009-04-03 12:03:39.000000', NULL, 1),
(5416803, 778063, 101256, '<td valign="top">Effective but it could have used a crop along the bottom to remove the out of focus branch.</td>', 'Effective but it could have used a crop along the bottom to remove the out of focus branch.', '2009-04-03 12:04:35.000000', NULL, 1),
(5416804, 777738, 101256, '<td valign="top">From a technical standpoint, this doesn''t work well at all. From an emotional standpoint, its complete with great color - there is a mystery here and it basically involves what the author wanted to convey to the viewer. That''s a plus because it allows for other interpretations.</td>', 'From a technical standpoint, this doesn''t work well at all. From an emotional standpoint, its complete with great color - there is a mystery here and it basically involves what the author wanted to convey to the viewer. That''s a plus because it allows for other interpretations.', '2009-04-03 12:04:46.000000', NULL, 1),
(5416806, 778010, 101256, '<td valign="top">Very interesting - an infrared view I would guess. Or infrared like which is almost the same thing.  The only problems I see with this are the fence post tops in the background which distract and don''t contribute to the overall composition in any way. Very interesting effect.  However, I don''t think it fits the overall intent of the challenge and would have worked better as an entry in an abstract challenge. I''ll split the difference. :&gt;)</td>', 'Very interesting - an infrared view I would guess. Or infrared like which is almost the same thing.  The only problems I see with this are the fence post tops in the background which distract and don''t contribute to the overall composition in any way. Very interesting effect.  However, I don''t think it fits the overall intent of the challenge and would have worked better as an entry in an abstract challenge. I''ll split the difference. :>)', '2009-04-03 12:05:04.000000', NULL, 1),
(5416807, 777229, 101256, '<td valign="top">A little less light in the background and more in the foreground would have made this a minimalist image that would be a top contender for a ribbon.</td>', 'A little less light in the background and more in the foreground would have made this a minimalist image that would be a top contender for a ribbon.', '2009-04-03 12:05:05.000000', NULL, 1),
(5416808, 778336, 101256, '<td valign="top">Great composition and technically all around nicely concieved.</td>', 'Great composition and technically all around nicely concieved.', '2009-04-03 12:05:08.000000', NULL, 1),
(5416809, 778217, 101256, '<td valign="top">Very nice - good DOF control and the color blends are very pleasing to the eye.  Not terribly interesting in context, but very well executed.</td>', 'Very nice - good DOF control and the color blends are very pleasing to the eye.  Not terribly interesting in context, but very well executed.', '2009-04-03 12:05:10.000000', NULL, 1),
(5416810, 778588, 101256, '<td valign="top">If this were a sky challenge, it would win hands down.  This is one instance where HDR creating a lasting impression on one hand and detracts from the images impact on the other. Additionally, the image appears to be just so ever over sharpened - it has that kind of feel to it.  I think this might have been better working with one of the HDR images used to produce instead of combining to get the HDR effect.</td>', 'If this were a sky challenge, it would win hands down.  This is one instance where HDR creating a lasting impression on one hand and detracts from the images impact on the other. Additionally, the image appears to be just so ever over sharpened - it has that kind of feel to it.  I think this might have been better working with one of the HDR images used to produce instead of combining to get the HDR effect.', '2009-04-03 12:05:11.000000', NULL, 1),
(5416811, 777227, 101256, '<td valign="top">A slight change of angle to bring the back into focus would have significantly improved this effort.</td>', 'A slight change of angle to bring the back into focus would have significantly improved this effort.', '2009-04-03 12:05:14.000000', NULL, 1),
(5416812, 777893, 101256, '<td valign="top">A very interesting macro image - abstract without being overly so. Technically its perfect, but from an emotional impact, it''s average. Split the difference between the two.</td>', 'A very interesting macro image - abstract without being overly so. Technically its perfect, but from an emotional impact, it''s average. Split the difference between the two.', '2009-04-03 12:05:17.000000', NULL, 1),
(5416813, 778289, 101256, '<td valign="top">Purposeful and delicate at the same time - I think cropping the left hand stalk off would improve the image, but it''s fine as it is. Very nice.</td>', 'Purposeful and delicate at the same time - I think cropping the left hand stalk off would improve the image, but it''s fine as it is. Very nice.', '2009-04-03 12:05:19.000000', NULL, 1),
(5416814, 777038, 101256, '<td valign="top">A little more saturation would be a plus, but the pearlescent tone is wonderful. The fade from white to yellow to green is outstanding. Its far from a perfect image, but it works well - very nicely concieved and composed.</td>', 'A little more saturation would be a plus, but the pearlescent tone is wonderful. The fade from white to yellow to green is outstanding. Its far from a perfect image, but it works well - very nicely concieved and composed.', '2009-04-03 12:05:21.000000', NULL, 1),
(5416815, 778636, 101256, '<td valign="top">Very nice DOF control and excellant tonal range.  I wonder what this might look like in grayscale or black and white. It''s a good image - very nice.</td>', 'Very nice DOF control and excellant tonal range.  I wonder what this might look like in grayscale or black and white. It''s a good image - very nice.', '2009-04-03 12:05:23.000000', NULL, 1),
(5416817, 778362, 101256, '<td valign="top">If the bottom was cropped by a 1/3 or so, you would see a very different and very effective image - almost dreamlike. The curves of the flower would better compliment the subtle bokeh shape in the background much more effectively and the eye would have tracked this feature automatically. The crop would also have made for a much more pleasing image.</td>', 'If the bottom was cropped by a 1/3 or so, you would see a very different and very effective image - almost dreamlike. The curves of the flower would better compliment the subtle bokeh shape in the background much more effectively and the eye would have tracked this feature automatically. The crop would also have made for a much more pleasing image.', '2009-04-03 12:05:26.000000', NULL, 1),
(5416818, 778081, 101256, '<td valign="top">A ten, but the slight shift in focus detracts from its overall impact. I feel if it had been taken head on with the entire subject in focus, it would be a ten. A difficult shot and a very nicely concieved composition the just this one minor flaw.</td>', 'A ten, but the slight shift in focus detracts from its overall impact. I feel if it had been taken head on with the entire subject in focus, it would be a ten. A difficult shot and a very nicely concieved composition the just this one minor flaw.', '2009-04-03 12:05:32.000000', NULL, 1),
(5416819, 778228, 101256, '<td valign="top">Yes - my favorite type of image. Perfectly executed and composed.</td>', 'Yes - my favorite type of image. Perfectly executed and composed.', '2009-04-03 12:05:36.000000', NULL, 1),
(5416820, 778641, 101256, '<td valign="top">Elegant and complex at the same time. I would have like to see a little more light on the subject to bring out a little less saturatin, but that''s me.</td>', 'Elegant and complex at the same time. I would have like to see a little more light on the subject to bring out a little less saturatin, but that''s me.', '2009-04-03 12:05:42.000000', NULL, 1),
(5416822, 777110, 101256, '<td valign="top">Very ethereal - mystical one might say. It''s a beautiful image with the whites right on the edge. If it were allowed, I might have might up the purple just a litte to give the image more ooomph (is that a word?), but it''s fine the way it is. Well done.</td>', 'Very ethereal - mystical one might say. It''s a beautiful image with the whites right on the edge. If it were allowed, I might have might up the purple just a litte to give the image more ooomph (is that a word?), but it''s fine the way it is. Well done.', '2009-04-03 12:08:12.000000', NULL, 1),
(5416823, 777625, 101256, '<td valign="top">Pefect.</td>', 'Pefect.', '2009-04-03 12:08:29.000000', NULL, 1),
(5416824, 778204, 101256, '<td valign="top">Arrrgh - I give up. Another top contender - if I see another, I''m just not going to comment. :&gt;) Just give it a ten.</td>', 'Arrrgh - I give up. Another top contender - if I see another, I''m just not going to comment. :>) Just give it a ten.', '2009-04-03 12:08:32.000000', NULL, 1),
(5416825, 776773, 101256, '<td valign="top">Simple, elegant, minimalist with incredible impact and precise, yet subtle detail. A wonderful still life.  Well done.</td>', 'Simple, elegant, minimalist with incredible impact and precise, yet subtle detail. A wonderful still life.  Well done.', '2009-04-03 12:08:35.000000', NULL, 1),
(5416828, 778549, 101256, '<td valign="top">Interesting, but overly busy and just right on the edge of being focused. The green bleed over into the branch stems are a negative - it''s overly green if you will.</td>', 'Interesting, but overly busy and just right on the edge of being focused. The green bleed over into the branch stems are a negative - it''s overly green if you will.', '2009-04-03 12:11:31.000000', NULL, 1),
(5416830, 777959, 101256, '<td valign="top">Not a perfect image, but close. The little minor nagging issues like the pollens which look like flawed pixels for instance and the slight out of focus appearance on the lower left.  On the other hand, it has significant beauty in and of itself and I feel should be rated that way.</td>', 'Not a perfect image, but close. The little minor nagging issues like the pollens which look like flawed pixels for instance and the slight out of focus appearance on the lower left.  On the other hand, it has significant beauty in and of itself and I feel should be rated that way.', '2009-04-03 12:13:44.000000', NULL, 1),
(5416836, 778307, 101256, '<td valign="top">The frame is a negative for me - its meaningless in context and does nothing for the eye to help appreciate the image. Its a major flaw for me and in my opinion lowers what otherwise would have been a 9 to a 6 in terms of visual impact. Technically it is a wonderful blend of detail and color - the frame had influenced my opinion significantly. Sorry.</td>', 'The frame is a negative for me - its meaningless in context and does nothing for the eye to help appreciate the image. Its a major flaw for me and in my opinion lowers what otherwise would have been a 9 to a 6 in terms of visual impact. Technically it is a wonderful blend of detail and color - the frame had influenced my opinion significantly. Sorry.', '2009-04-03 12:16:56.000000', NULL, 1),
(5416838, 778079, 101256, '<td valign="top">This would have worked better if the DOF were reversed with the central focus being the tip of the leaf being the central subject gently fading into the background.</td>', 'This would have worked better if the DOF were reversed with the central focus being the tip of the leaf being the central subject gently fading into the background.', '2009-04-03 12:17:52.000000', NULL, 1),
(5416845, 776898, 101256, '<td valign="top">Another frame problem, although this isnt as obvious as the other image that had one. I don''t mind frames - in fact, they can add significantly to any given image if handled properly.  Transparent frames as part of the image are, to me anyway, a major flaw because it doesn''t add, but subtracts from the subject.</td>', 'Another frame problem, although this isnt as obvious as the other image that had one. I don''t mind frames - in fact, they can add significantly to any given image if handled properly.  Transparent frames as part of the image are, to me anyway, a major flaw because it doesn''t add, but subtracts from the subject.', '2009-04-03 12:19:54.000000', NULL, 1),
(5416853, 777938, 101256, '<td valign="top">Too much low light - could have been much better as an effective night shot with a little slower shutter speed.  Then again, that would have created a different problem with the lighting in the background. A very difficult shot even for an expert with all the technical tools available from the camera to post processing.</td>', 'Too much low light - could have been much better as an effective night shot with a little slower shutter speed.  Then again, that would have created a different problem with the lighting in the background. A very difficult shot even for an expert with all the technical tools available from the camera to post processing.', '2009-04-03 12:22:22.000000', NULL, 1),
(5416856, 777139, 101256, '<td valign="top">A watercolor effect that I appreciate very much. Subtle tones and shades enhance the image and the very slight soft focus is very effective.  Well done.</td>', 'A watercolor effect that I appreciate very much. Subtle tones and shades enhance the image and the very slight soft focus is very effective.  Well done.', '2009-04-03 12:23:23.000000', NULL, 1),
(5416861, 777453, 101256, '<td valign="top">I don''t think the green to yellow transitions are s good as they could be. Perhaps backing off on the focal length would have helped - it just seems overdone and not as subtle as they should be.</td>', 'I don''t think the green to yellow transitions are s good as they could be. Perhaps backing off on the focal length would have helped - it just seems overdone and not as subtle as they should be.', '2009-04-03 12:26:21.000000', NULL, 1),
(5416862, 778676, 101256, '<td valign="top">The rather odd edge lighting is a distracting from an otherwise great image. A little softer light would have made this a terrific conversion. Just a touch too much illumination.</td>', 'The rather odd edge lighting is a distracting from an otherwise great image. A little softer light would have made this a terrific conversion. Just a touch too much illumination.', '2009-04-03 12:27:52.000000', NULL, 1),
(5416864, 777627, 101256, '<td valign="top">Well, I''m not sure about this at all - it''s clearly outside the challenge specifications as the Nerf football isn''t a flower, but the piece of deadwood is - in a sense. I can''t rate it because I''m not at all sure of the author''s intent.<br/> <br/>On second thought, I am going to rate it - low unfortunately.</td>', 'Well, I''m not sure about this at all - it''s clearly outside the challenge specifications as the Nerf football isn''t a flower, but the piece of deadwood is - in a sense. I can''t rate it because I''m not at all sure of the author''s intent. On second thought, I am going to rate it - low unfortunately.', '2009-04-03 12:28:46.000000', NULL, 1),
(5416869, 778047, 101256, '<td valign="top">The intent is understood, but the whites are right at the margins of being overdone. A slightly different angle or even a little under exposure would have helped a lot. From a composition standpoint, its very creative and it''s impact is terrific - its the technicals that distort the impact.</td>', 'The intent is understood, but the whites are right at the margins of being overdone. A slightly different angle or even a little under exposure would have helped a lot. From a composition standpoint, its very creative and it''s impact is terrific - its the technicals that distort the impact.', '2009-04-03 12:31:06.000000', NULL, 1),
(5416873, 778438, 101256, '<td valign="top">Offset a little too far to rate a perfect score - I might have back off a little and gotten a little sharper control on DOF and room to get a really good offset crop.</td>', 'Offset a little too far to rate a perfect score - I might have back off a little and gotten a little sharper control on DOF and room to get a really good offset crop.', '2009-04-03 12:32:40.000000', NULL, 1),
(5416877, 778643, 101256, '<td valign="top">Yes it is a sweet and simple image, but the extra leaf stem on the right is distracting with no context - minor flaw.  The other issue is the extra light on the stem - a little less exposure with a tweak in post processing would have made this an excellant image instead of an average image.</td>', 'Yes it is a sweet and simple image, but the extra leaf stem on the right is distracting with no context - minor flaw.  The other issue is the extra light on the stem - a little less exposure with a tweak in post processing would have made this an excellant image instead of an average image.', '2009-04-03 12:34:27.000000', NULL, 1),
(5416878, 778359, 101256, '<td valign="top">Excellant DOF control, but the subject is slighty affected by it. A different angle and slightly more focal length would have solved the problem and made this a top contender in my opinion.</td>', 'Excellant DOF control, but the subject is slighty affected by it. A different angle and slightly more focal length would have solved the problem and made this a top contender in my opinion.', '2009-04-03 12:36:15.000000', NULL, 1),
(5416880, 777770, 101256, '<td valign="top">Unfortunate - too much yellow. If the background were lighter allowing the flower to stand out, it would have been almost perfect.  Another idea would have been to use a contrasting color - not black because that would just make it cliche, but something different like a light purple or blue - magenta would be excellant.  The other issue is that it''s a tad over sharpened which I think the author overused to differentiate the flower from the background. Another reason to use a different background.</td>', 'Unfortunate - too much yellow. If the background were lighter allowing the flower to stand out, it would have been almost perfect.  Another idea would have been to use a contrasting color - not black because that would just make it cliche, but something different like a light purple or blue - magenta would be excellant.  The other issue is that it''s a tad over sharpened which I think the author overused to differentiate the flower from the background. Another reason to use a different background.', '2009-04-03 12:39:03.000000', NULL, 1),
(5416881, 777924, 101256, '<td valign="top">This has a subject problem - the bee is the focus. Also, the offset brings the eye to the background rather the foreground. A good effort as it blends the two challenges, but thats not the challenge.  :&gt;)  A slight change in angle and more of the flower would make it a good image.</td>', 'This has a subject problem - the bee is the focus. Also, the offset brings the eye to the background rather the foreground. A good effort as it blends the two challenges, but thats not the challenge.  :>)  A slight change in angle and more of the flower would make it a good image.', '2009-04-03 12:41:02.000000', NULL, 1),
(5416882, 778515, 103470, '<td valign="top">This picture is really out of focus otherwise it would have been extremly good</td>', 'This picture is really out of focus otherwise it would have been extremly good', '2009-04-03 12:41:19.000000', NULL, 1),
(5416884, 778671, 101256, '<td valign="top">Interesting, but way too tall an image to be truly effective and pleasing to the eye. I might had cropped the bottom third off to increase it''s overall effectiveness. Nice color control on the green.</td>', 'Interesting, but way too tall an image to be truly effective and pleasing to the eye. I might had cropped the bottom third off to increase it''s overall effectiveness. Nice color control on the green.', '2009-04-03 12:42:26.000000', NULL, 1),
(5416886, 777363, 103470, '<td valign="top">This is such an intresting idea/photograph!</td>', 'This is such an intresting idea/photograph!', '2009-04-03 12:43:40.000000', NULL, 1),
(5416887, 777361, 103470, '<td valign="top">Good job making this plant look fantastic - though its dying on the ledge in our kitchen-</td>', 'Good job making this plant look fantastic - though its dying on the ledge in our kitchen-', '2009-04-03 12:44:44.000000', NULL, 1),
(5416889, 778181, 101256, '<td valign="top">Judging and rating an image like this is difficult. There is a dual subject here and I''m not sure its within the "spirit" of the challenge.  On the one hand, the offset flowers are well within the scope of the challenge, on the other hand, the couple is a different story within the story of the bouquet. Very similar to an earlier image I had difficulty rating.<br/> <br/>Ah the heck with it - well done.</td>', 'Judging and rating an image like this is difficult. There is a dual subject here and I''m not sure its within the "spirit" of the challenge.  On the one hand, the offset flowers are well within the scope of the challenge, on the other hand, the couple is a different story within the story of the bouquet. Very similar to an earlier image I had difficulty rating. Ah the heck with it - well done.', '2009-04-03 12:45:32.000000', NULL, 1),
(5416891, 778606, 101256, '<td valign="top">I think this is a great image - just misplaced in the challenge. The subject matter appears to me to be the wood pilings and not the flora surrounding them.  The overall color tone is interesting and subtle. However, the net effect isnt positive for me.</td>', 'I think this is a great image - just misplaced in the challenge. The subject matter appears to me to be the wood pilings and not the flora surrounding them.  The overall color tone is interesting and subtle. However, the net effect isnt positive for me.', '2009-04-03 12:47:37.000000', NULL, 1),
(5416931, 778307, 101445, '<td valign="top">this is one of my favorites of the challenge</td>', 'this is one of my favorites of the challenge', '2009-04-03 13:17:44.000000', NULL, 1),
(5416932, 777625, 101445, '<td valign="top">this is one of my favorites of the challenge</td>', 'this is one of my favorites of the challenge', '2009-04-03 13:17:57.000000', NULL, 1),
(5416933, 777970, 101445, '<td valign="top">This is one on my favorites of the challenge</td>', 'This is one on my favorites of the challenge', '2009-04-03 13:18:11.000000', NULL, 1),
(5416960, 777737, 104625, '<td valign="top">I LOVE what you''ve done with the lighting.  This is an absolutely stunning photo.</td>', 'I LOVE what you''ve done with the lighting.  This is an absolutely stunning photo.', '2009-04-03 13:37:16.000000', NULL, 1),
(5416964, 777930, 56502, '<td valign="top">This is such a great idea! <br/>It''s a pity it''s a bit dark, but with 1/4 of second probably all you could get out of it. Longer exposure - motion blur, higher ISO - more noise.<br/>Given that, good job!</td>', 'This is such a great idea! It''s a pity it''s a bit dark, but with 1/4 of second probably all you could get out of it. Longer exposure - motion blur, higher ISO - more noise.Given that, good job!', '2009-04-03 13:39:34.000000', NULL, 1),
(5417016, 778010, 98141, '<td valign="top">Very unique subject, pp and shot altogether. I think the black dots across the horizon are a bit distracting, but I''m looking forward to reading more about how you took/processed this. Great coloring.</td>', 'Very unique subject, pp and shot altogether. I think the black dots across the horizon are a bit distracting, but I''m looking forward to reading more about how you took/processed this. Great coloring.', '2009-04-03 14:22:03.000000', NULL, 1),
(5417019, 777410, 98141, '<td valign="top">Elegant and beautiful. The red pops really nicely and it''s a really nice bloom. I could see this on a Hallmark card.</td>', 'Elegant and beautiful. The red pops really nicely and it''s a really nice bloom. I could see this on a Hallmark card.', '2009-04-03 14:22:48.000000', NULL, 1),
(5417021, 778104, 98141, '<td valign="top">Everything here is so soft, whispy, I like the colors a lot as well, great DOF the background is like a watercolor.</td>', 'Everything here is so soft, whispy, I like the colors a lot as well, great DOF the background is like a watercolor.', '2009-04-03 14:23:15.000000', NULL, 1),
(5417024, 777626, 98141, '<td valign="top">Very excellent use of lighting here, I love the autumnal coloring but the darkness of the silhouettes of the veins. Really great composition as well.</td>', 'Very excellent use of lighting here, I love the autumnal coloring but the darkness of the silhouettes of the veins. Really great composition as well.', '2009-04-03 14:24:18.000000', NULL, 1),
(5417027, 778269, 98141, '<td valign="top">I think the subject of this photo is a person rather than the plant and so I have a hard time seeing this meet the spirit of the challenge, but there is some flora included, so I won''t comment with DNMC. I think I''d like this better if the man weren''t looking right into the camera, as I feel like the girl is the subject but his eyes take away from her beauty. A shallower DOF would fix this or a different expression/pose. I like that the color of the flower matches the dress so well.</td>', 'I think the subject of this photo is a person rather than the plant and so I have a hard time seeing this meet the spirit of the challenge, but there is some flora included, so I won''t comment with DNMC. I think I''d like this better if the man weren''t looking right into the camera, as I feel like the girl is the subject but his eyes take away from her beauty. A shallower DOF would fix this or a different expression/pose. I like that the color of the flower matches the dress so well.', '2009-04-03 14:27:03.000000', NULL, 1),
(5417028, 777860, 98141, '<td valign="top">Okay, there''s a lot going on here, some of it good and some of it not so good. I love the way the yellow pops, it''s nice and saturate, and I like how many insects are included, it makes for a great scene. The background is a little busy, lots of lines going everywhere and although the bee is in focus, the flowers, which are bright and the first thing the eye tries to focus on, see to be oof enough to be distracting. I also think that the green leaf that extends right up from the bottom of the frame is distracting.</td>', 'Okay, there''s a lot going on here, some of it good and some of it not so good. I love the way the yellow pops, it''s nice and saturate, and I like how many insects are included, it makes for a great scene. The background is a little busy, lots of lines going everywhere and although the bee is in focus, the flowers, which are bright and the first thing the eye tries to focus on, see to be oof enough to be distracting. I also think that the green leaf that extends right up from the bottom of the frame is distracting.', '2009-04-03 14:29:18.000000', NULL, 1),
(5417030, 778218, 98141, '<td valign="top">I think this truly covers more the definition of flora than a lot of the other shots in this challenge. However, even though it meets the spirit of the challenge perfectly, as a picture it leaves a little to be desired. First of all, the horizon is not straight. Second, I think if you had something (a tree, a flower, a leaf of grass, etc.) as a subject and then had all the rest of this flora as a background it would have more focus to it. Right now it almost feels like an accidental shot because there''s no specific subject and it doesn''t really offer anything impressive as far as a landscape goes.</td>', 'I think this truly covers more the definition of flora than a lot of the other shots in this challenge. However, even though it meets the spirit of the challenge perfectly, as a picture it leaves a little to be desired. First of all, the horizon is not straight. Second, I think if you had something (a tree, a flower, a leaf of grass, etc.) as a subject and then had all the rest of this flora as a background it would have more focus to it. Right now it almost feels like an accidental shot because there''s no specific subject and it doesn''t really offer anything impressive as far as a landscape goes.', '2009-04-03 14:33:37.000000', NULL, 1),
(5417034, 778266, 98141, '<td valign="top">I don''t think that this is in very good focus and it seems rather dark. I think the composition is a little awkward since the macro doesn''t fill the shot but we can''t see the whole bloom either.</td>', 'I don''t think that this is in very good focus and it seems rather dark. I think the composition is a little awkward since the macro doesn''t fill the shot but we can''t see the whole bloom either.', '2009-04-03 14:34:44.000000', NULL, 1),
(5417041, 778265, 98141, '<td valign="top">This is a great flora shot, really captures the spirit of the challenge. Lots of variety, very specific location, I think this is great.</td>', 'This is a great flora shot, really captures the spirit of the challenge. Lots of variety, very specific location, I think this is great.', '2009-04-03 14:37:54.000000', NULL, 1),
(5417042, 777757, 98141, '<td valign="top">Nothing here really seems to be in sharp focus to me. I''d suggest really filling the frame for shots like this, the white space in the upper right corner and along the top edge is a bit distracting.</td>', 'Nothing here really seems to be in sharp focus to me. I''d suggest really filling the frame for shots like this, the white space in the upper right corner and along the top edge is a bit distracting.', '2009-04-03 14:37:55.000000', NULL, 1),
(5417044, 778014, 98141, '<td valign="top">Shot seems somewhat out of focus and a little dull. The composition/angle is a little awkward and doesn''t show off the plant well. I''d suggest filling the frame completely for a well-filled-out plant like this, I don''t think the background does much to enhance the subject here.</td>', 'Shot seems somewhat out of focus and a little dull. The composition/angle is a little awkward and doesn''t show off the plant well. I''d suggest filling the frame completely for a well-filled-out plant like this, I don''t think the background does much to enhance the subject here.', '2009-04-03 14:38:52.000000', NULL, 1),
(5417047, 777363, 98141, '<td valign="top">A really interesting shot, very clever concept. I think with one more egg being completely whole it would feel more complete, but the colors and lighting look great.</td>', 'A really interesting shot, very clever concept. I think with one more egg being completely whole it would feel more complete, but the colors and lighting look great.', '2009-04-03 14:41:21.000000', NULL, 1),
(5417048, 778588, 98141, '<td valign="top">Great composition and great, saturated colors. A simple comment for a simple, but beautiful, capture.</td>', 'Great composition and great, saturated colors. A simple comment for a simple, but beautiful, capture.', '2009-04-03 14:43:14.000000', NULL, 1),
(5417049, 778621, 98141, '<td valign="top">I was expecting to see more shots like this for this challenge. Great composition and colors here, I think the texture of the bark is what really makes this interesting.</td>', 'I was expecting to see more shots like this for this challenge. Great composition and colors here, I think the texture of the bark is what really makes this interesting.', '2009-04-03 14:44:06.000000', NULL, 1),
(5417051, 778065, 98141, '<td valign="top">Great location to really capture the spirit of the challenge. This is definitely flora, a variety and very location-specific. I am jealous of the clear, blue sky. I think this would be stronger with something as the star of the show, so to speak. It''s not really inclusive enough for a landscape but it''s not macro enough for just a flower to stand out.I think if there were a tree or a blossom that was the central subject it would be more visually pleasing, but very good job all the same.</td>', 'Great location to really capture the spirit of the challenge. This is definitely flora, a variety and very location-specific. I am jealous of the clear, blue sky. I think this would be stronger with something as the star of the show, so to speak. It''s not really inclusive enough for a landscape but it''s not macro enough for just a flower to stand out.I think if there were a tree or a blossom that was the central subject it would be more visually pleasing, but very good job all the same.', '2009-04-03 14:46:08.000000', NULL, 1),
(5417054, 777402, 98141, '<td valign="top">Wow, this is stunning. Another one that I think belongs on the front page, I have my top three picked now :) Great capture, beautiful location, and I love that it includes a variety of flora instead of just one flower or plant. Really nice job.</td>', 'Wow, this is stunning. Another one that I think belongs on the front page, I have my top three picked now :) Great capture, beautiful location, and I love that it includes a variety of flora instead of just one flower or plant. Really nice job.', '2009-04-03 14:49:47.000000', NULL, 1),
(5417055, 777496, 98141, '<td valign="top">I like the location, this is elegant like a painting, but I think that this pic would do better if the contrast were a bit stronger.</td>', 'I like the location, this is elegant like a painting, but I think that this pic would do better if the contrast were a bit stronger.', '2009-04-03 14:49:51.000000', NULL, 1),
(5417056, 778270, 98141, '<td valign="top">Wow, I can''t wait to read about your setup/pp for this. I think this will be on the front page soon. Fantastic shot, great lighting and the colors are lovely.</td>', 'Wow, I can''t wait to read about your setup/pp for this. I think this will be on the front page soon. Fantastic shot, great lighting and the colors are lovely.', '2009-04-03 14:50:10.000000', NULL, 1),
(5417057, 777970, 98141, '<td valign="top">This is a really neat shot, green and white are great colors too (MSU Alum here). It''s different from everything else I''ve seen in this challenge, great job.</td>', 'This is a really neat shot, green and white are great colors too (MSU Alum here). It''s different from everything else I''ve seen in this challenge, great job.', '2009-04-03 14:50:11.000000', NULL, 1),
(5417058, 778536, 98141, '<td valign="top">I think this is jaw-dropping.I look forward to reading about the setup and pp for this one. Great lighting. I think we will see this on the front page.</td>', 'I think this is jaw-dropping.I look forward to reading about the setup and pp for this one. Great lighting. I think we will see this on the front page.', '2009-04-03 14:50:13.000000', NULL, 1),
(5417070, 777810, 104950, '<td valign="top">I would enjoy this image more if it were "softer". <br/>In particular the jpg artifacts capture my attention too much.<br/>I think less contrast and less saturation could make the image more graceful.</td>', 'I would enjoy this image more if it were "softer". In particular the jpg artifacts capture my attention too much.I think less contrast and less saturation could make the image more graceful.', '2009-04-03 15:22:51.000000', NULL, 1),
(5417212, 777030, 43774, '<td valign="top">I like that you filled the frame. Seems to me it could be a bit sharper but I like tack sharp photos.</td>', 'I like that you filled the frame. Seems to me it could be a bit sharper but I like tack sharp photos.', '2009-04-03 17:19:26.000000', NULL, 1),
(5417213, 778212, 43774, '<td valign="top">Pretty colour, very clear, nice. But it should really be bigger for a challenge.</td>', 'Pretty colour, very clear, nice. But it should really be bigger for a challenge.', '2009-04-03 17:19:54.000000', NULL, 1),
(5417214, 778366, 43774, '<td valign="top">Beautiful colour and great exposure.</td>', 'Beautiful colour and great exposure.', '2009-04-03 17:20:07.000000', NULL, 1);
