(5417215, 777110, 43774, '<td valign="top">I''d like to see this a bit brighter and with a bit more contrast. It seems washed out and a bit noisy to me. I like that you filled the frame.</td>', 'I''d like to see this a bit brighter and with a bit more contrast. It seems washed out and a bit noisy to me. I like that you filled the frame.', '2009-04-03 17:20:59.000000', NULL, 1),
(5417217, 776773, 43774, '<td valign="top">Suggestive!! Very good exposure and colour.</td>', 'Suggestive!! Very good exposure and colour.', '2009-04-03 17:21:15.000000', NULL, 1),
