(5419671, 778204, 74911, '<td valign="top">Great lighting and composition. But looks a little over-sharpened for me. Framing also works here.</td>', 'Great lighting and composition. But looks a little over-sharpened for me. Framing also works here.', '2009-04-05 15:03:49.000000', NULL, 1),
(5419675, 778622, 74911, '<td valign="top">I can see the efforts here in getting the exposure right on all the four Orchids. I am not able to appreciate the border though. Great result.</td>', 'I can see the efforts here in getting the exposure right on all the four Orchids. I am not able to appreciate the border though. Great result.', '2009-04-05 15:04:55.000000', NULL, 1),
(5419676, 778575, 74911, '<td valign="top">Great compostion and colors. Nice use of shallow DOF. Hope this does well.</td>', 'Great compostion and colors. Nice use of shallow DOF. Hope this does well.', '2009-04-05 15:05:43.000000', NULL, 1),
(5419677, 778473, 74911, '<td valign="top">Great tones. Nice compo. Not sure if the unbalanced lighting work here. I would have either placed all of them under sunlight or all under shadow. But seems interesting.</td>', 'Great tones. Nice compo. Not sure if the unbalanced lighting work here. I would have either placed all of them under sunlight or all under shadow. But seems interesting.', '2009-04-05 15:07:17.000000', NULL, 1),
(5419678, 778211, 74911, '<td valign="top">I like the simplicity of this image. Great colors too. Nice details on the petal. The subtle framing compliments the picture very well.</td>', 'I like the simplicity of this image. Great colors too. Nice details on the petal. The subtle framing compliments the picture very well.', '2009-04-05 15:08:29.000000', NULL, 1),
