(5421888, 777893, 31456, '<td valign="top">I like everything about this image. DOF, color, everything.</td>', 'I like everything about this image. DOF, color, everything.', '2009-04-06 14:12:04.000000', NULL, 1),
(5421889, 777954, 31456, '<td valign="top">I like the bold colors, but in some spots it hurts the eyes.</td>', 'I like the bold colors, but in some spots it hurts the eyes.', '2009-04-06 14:12:24.000000', NULL, 1),
(5421890, 778403, 31456, '<td valign="top">Nice, but I''d like it to be sharper in some spots. Also, the color is a bit <i>too</i> bland.</td>', 'Nice, but I''d like it to be sharper in some spots. Also, the color is a bit too bland.', '2009-04-06 14:12:54.000000', NULL, 1),
(5421894, 777359, 31456, '<td valign="top">The colors look posterized here, like the contrast was upped too much. It''s also making the image look "vintage," which (intended or not) is not working for me. Could''ve used a less busy background, too.</td>', 'The colors look posterized here, like the contrast was upped too much. It''s also making the image look "vintage," which (intended or not) is not working for me. Could''ve used a less busy background, too.', '2009-04-06 14:14:37.000000', NULL, 1),
(5421897, 778400, 31456, '<td valign="top">The subject is tack-sharp, but the very blurry blades of grass in the foreground are a bit too blurry for me and become distracting. A tighter crop on the right may have helped; that or a slightly smaller aperture to give them a bit more sharpness.</td>', 'The subject is tack-sharp, but the very blurry blades of grass in the foreground are a bit too blurry for me and become distracting. A tighter crop on the right may have helped; that or a slightly smaller aperture to give them a bit more sharpness.', '2009-04-06 14:16:37.000000', NULL, 1),
(5421899, 777902, 31456, '<td valign="top">This is the second abstract one I see in this, but in this case, it has an element that has been overused (especially here at DPC). Nice idea, good colors, a very good image overall... but it doesn''t pop as much because of the technique''s overuse in the last few years.</td>', 'This is the second abstract one I see in this, but in this case, it has an element that has been overused (especially here at DPC). Nice idea, good colors, a very good image overall... but it doesn''t pop as much because of the technique''s overuse in the last few years.', '2009-04-06 14:18:06.000000', NULL, 1),
(5421903, 777809, 31456, '<td valign="top">The white part at the top is distracting. Other than that, it''s a good image, though I would''ve kept trying different angles until I found a better one. I like the country theme.</td>', 'The white part at the top is distracting. Other than that, it''s a good image, though I would''ve kept trying different angles until I found a better one. I like the country theme.', '2009-04-06 14:20:37.000000', NULL, 1),
(5421905, 778143, 31456, '<td valign="top">The DOF is a little too shallow, and I''m having trouble seeing how the overall effect could be achieved without selective desat, which I don''t think is legal in Basic Editing. Anyway, no voting based on editing rules, so it''s still a 7 to me.</td>', 'The DOF is a little too shallow, and I''m having trouble seeing how the overall effect could be achieved without selective desat, which I don''t think is legal in Basic Editing. Anyway, no voting based on editing rules, so it''s still a 7 to me.', '2009-04-06 14:23:31.000000', NULL, 1),
(5421907, 778003, 31456, '<td valign="top">DOF just a tad too shallow, and would''ve liked more symmetry between the background on the left and the right. Also, the light is a little distracting, creating a "hot spot" and a big shadow. Still a good image overall, with bright colors and a good level of detail in the sharp spots.</td>', 'DOF just a tad too shallow, and would''ve liked more symmetry between the background on the left and the right. Also, the light is a little distracting, creating a "hot spot" and a big shadow. Still a good image overall, with bright colors and a good level of detail in the sharp spots.', '2009-04-06 14:25:39.000000', NULL, 1),
