(5422533, 778226, 79720, '<td valign="top">I think the post processing may detract a little from the final image, although I can see Leary staring at this, rapt. ;)</td>', 'I think the post processing may detract a little from the final image, although I can see Leary staring at this, rapt. ;)', '2009-04-06 19:37:51.000000', NULL, 1),
(5422535, 777019, 79720, '<td valign="top">Very nice macro. The light source could have used some diffraction, the highlights are a bit strong.</td>', 'Very nice macro. The light source could have used some diffraction, the highlights are a bit strong.', '2009-04-06 19:38:47.000000', NULL, 1),
(5422536, 777754, 79720, '<td valign="top">I like the composition, the contrast has left the shadows devoid of any detail.</td>', 'I like the composition, the contrast has left the shadows devoid of any detail.', '2009-04-06 19:39:33.000000', NULL, 1),
(5422541, 778074, 79720, '<td valign="top">...but excellent focus!</td>', '...but excellent focus!', '2009-04-06 19:41:39.000000', NULL, 1),
(5422543, 778199, 79720, '<td valign="top">Seems as though the saturation has really taken over the detail.</td>', 'Seems as though the saturation has really taken over the detail.', '2009-04-06 19:42:40.000000', NULL, 1),
(5422544, 778622, 79720, '<td valign="top">Very nice lighting effect!</td>', 'Very nice lighting effect!', '2009-04-06 19:43:12.000000', NULL, 1),
(5422547, 777919, 79720, '<td valign="top">Zoom in closer and you''d have a nice "Texture" entry. ;)</td>', 'Zoom in closer and you''d have a nice "Texture" entry. ;)', '2009-04-06 19:43:54.000000', NULL, 1),
(5422548, 778204, 79720, '<td valign="top">Very nicely lit.</td>', 'Very nicely lit.', '2009-04-06 19:44:21.000000', NULL, 1),
(5422754, 778639, 79720, '<td valign="top">hmmmm...Big Sur? I think I saw another entry from a nearly identical location, wtih a touch more DoF. ;)</td>', 'hmmmm...Big Sur? I think I saw another entry from a nearly identical location, wtih a touch more DoF. ;)', '2009-04-06 21:13:00.000000', NULL, 1),
